)

const topoFromLabListTimeout = 30 * time.Second

type ClabOption func(c *CLab) error

// WithLabOwner sets the owner label for all nodes in the lab.
// Only users in the clab_admins group can set a custom owner.
func WithLabOwner(owner string) ClabOption {
	return func(c *CLab) error {
		currentUser, err := user.Current()
		if err != nil {
			log.Warn(
				"Failed to get current user when trying to set the custom lab owner",
				"error",
				err,
			)

			return nil
		}

		if isClabAdmin, err := clabutils.UserInUnixGroup(currentUser.Username,
			"clab_admins"); err == nil && isClabAdmin {
			c.customOwner = owner
		} else if owner != "" {
			log.Warn(
				"Only users in clab_admins group can set custom owner. Using current user as owner.",
			)
		}

		return nil
	}
}

func WithTimeout(dur time.Duration) ClabOption {
	return func(c *CLab) error {
		if dur <= 0 {
			return errors.New("zero or negative timeouts are not allowed")
		}

		c.timeout = dur

		return nil
	}
}

// WithTopologyName sets the name of the lab/topology
// to the provided string.
func WithTopologyName(n string) ClabOption {
	return func(c *CLab) error {
		c.Config.Name = n

		return nil
	}
}

// WithSkippedBindsPathsCheck skips the binds paths checks.
func WithSkippedBindsPathsCheck() ClabOption {
	return func(c *CLab) error {
		c.checkBindsPaths = false

		return nil
	}
}

// WithSkippedMgmtNetLinksCheck skips the mgmt-net link checks.
// It must precede the options that load the topology, as those run the checks.
func WithSkippedMgmtNetLinksCheck() ClabOption {
	return func(c *CLab) error {
		c.checkMgmtNetLinks = false

		return nil
	}
}

// checkMgmtOverride rejects management network flags for topologies with several networks,
// since a flag cannot tell which network it applies to.
func (c *CLab) checkMgmtOverride() error {
	if len(c.Config.MgmtNetworks) > 1 {
		return errors.New(
			"management network flags cannot be used with multiple management networks",
		)
	}
	return nil
}

// WithManagementNetworkName sets the name of the
// management network that is to be used.
func WithManagementNetworkName(n string) ClabOption {
	return func(c *CLab) error {
		if err := c.checkMgmtOverride(); err != nil {
			return err
		}
		c.Config.Mgmt.Network = n
		c.managementNetworkOverridden = true

		return nil
	}
}

// WithManagementIpv4Subnet defined the IPv4 subnet
// that will be used for the mgmt network.
func WithManagementIpv4Subnet(s string) ClabOption {
	return func(c *CLab) error {
		if err := c.checkMgmtOverride(); err != nil {
			return err
		}
		c.Config.Mgmt.IPv4Subnet = s
		c.managementNetworkOverridden = true

		return nil
	}
}

// WithManagementIpv6Subnet defined the IPv6 subnet
// that will be used for the mgmt network.
func WithManagementIpv6Subnet(s string) ClabOption {
	return func(c *CLab) error {
		if err := c.checkMgmtOverride(); err != nil {
			return err
		}
		c.Config.Mgmt.IPv6Subnet = s
		c.managementNetworkOverridden = true

		return nil
	}
}

// WithDependencyManager adds Dependency Manager.
func WithDependencyManager(dm clabcoredependency_manager.DependencyManager) ClabOption {
	return func(c *CLab) error {
		c.dependencyManager = dm

		return nil
	}
}

// WithDebug sets debug mode.
func WithDebug(debug bool) ClabOption {
	return func(c *CLab) error {
		c.Config.Debug = debug

		return nil
	}
}

// WithRuntime option sets a container runtime to be used by containerlab.
func WithRuntime(name string, rtconfig *clabruntime.RuntimeConfig) ClabOption {
	return func(c *CLab) error {
		name = resolveRuntimeName(name)

		if clablabruntime.IsLabRuntimeName(name) {
			c.globalRuntimeName = name

			lr, err := clablabruntime.Init(name, clablabruntime.Config{
				Timeout:   runtimeTimeout(rtconfig),
				Namespace: labRuntimeNamespace(rtconfig),
				// The kind registry is populated before options run; lab runtimes use it to
				// predict the lifecycle impact of link changes in their plan.
				KindLinkApplyMode: func(kind string) string {
					return string(c.Reg.LinkApplyModeForKind(kind))
				},
			})
			if err != nil {
				return fmt.Errorf("failed to init the lab runtime: %w", err)
			}

			c.LabRuntime = lr

			return nil
		}

		name, rInit, err := RuntimeInitializer(name)
		if err != nil {
			return err
		}
		c.globalRuntimeName = name

		r := rInit()

		log.Debugf("Running runtime.Init with params %+v and %+v", rtconfig, c.Config.Mgmt)

		err = r.Init(
			clabruntime.WithConfig(rtconfig),
			clabruntime.WithMgmtNet(c.Config.Mgmt),
		)
		if err != nil {
			return fmt.Errorf("failed to init the container runtime: %v", err)
		}

		c.Runtimes[name] = r

		log.Debugf("initialized a runtime with params %+v", r)

		return nil
	}
}

// WithLabRuntimeIdentity makes every lab runtime call of this CLab act as the given Kubernetes
// identity, through user impersonation. A server that runs labs for many users sets it per user;
// the zero identity acts with the kubeconfig as it is. Local container runtimes ignore it.
func WithLabRuntimeIdentity(identity clablabruntime.Identity) ClabOption {
	return func(c *CLab) error {
		c.labRuntimeIdentity = identity

		return nil
	}
}

// LabRuntimeIdentity returns the Kubernetes identity lab runtime calls act as.
func (c *CLab) LabRuntimeIdentity() clablabruntime.Identity {
	return c.labRuntimeIdentity
}

func labRuntimeNamespace(config *clabruntime.RuntimeConfig) string {
	if config == nil {
		return ""
	}

	return config.LabNamespace
}

func runtimeTimeout(rtconfig *clabruntime.RuntimeConfig) time.Duration {
	if rtconfig == nil {
		return 0
	}

	return rtconfig.Timeout
}

func WithKeepMgmtNet() ClabOption {
	return func(c *CLab) error {
		if c.LabRuntime != nil {
			log.Debug("Ignoring keep management network option for lab runtime",
				"runtime", c.globalRuntimeName)

			return nil
		}

		r := c.globalRuntime()
		if r == nil {
			return fmt.Errorf("container runtime %q is not initialized", c.globalRuntimeName)
		}

		r.WithKeepMgmtNet()

		return nil
	}
}

// WithTopologyVarsFiles records the topology template vars files on TopoPaths without loading a
// topology. Used when the CLI passes --vars without -t (e.g. destroy --all).
func WithTopologyVarsFiles(varsFiles []string) ClabOption {
	return func(c *CLab) error {
		if len(varsFiles) == 0 {
			return nil
		}

		for _, varsFile := range varsFiles {
			err := c.TopoPaths.AppendTopologyVarsFilePath(varsFile)
			if err != nil {
				return err
			}
		}
		return nil
	}
}

// WithTopologyEnv sets the env vars (key=value entries) that are used instead of the
// process environment to expand env vars in the topology and in startup config templates,
// and that __IMPORT_ENVS imports. This keeps the environment of a program that embeds
// containerlab, e.g. its secrets, out of the topologies it deploys.
// It must precede the options that load the topology.
func WithTopologyEnv(env []string) ClabOption {
	return func(c *CLab) error {
		if c.TopoPaths.TopologyFileIsSet() {
			return errors.New("topology env must be set before the topology is loaded")
		}

		// copy into a non-nil slice, so that an empty env doesn't fall back to the process env
		c.topologyEnv = append(make([]string, 0, len(env)), env...)

		return nil
	}
}

func WithTopoPath(path string, varsFiles []string) ClabOption {
	return func(c *CLab) error {
		file, err := c.ProcessTopoPath(path)
		if err != nil {
			return err
		}

		if err := c.LoadTopologyFromFile(file, varsFiles); err != nil {
			return fmt.Errorf("failed to read topology file: %v", err)
		}

		return c.initMgmtNetwork()
	}
}

// WithTopoBackup creates a backup of the topology file.
func WithTopoBackup(path string) ClabOption {
	return func(c *CLab) error {
		// create a backup file for the topology file
		backupFPath := c.TopoPaths.TopologyBakFileAbsPath()

		err := clabutils.CopyFile(
			context.Background(),
			path,
			backupFPath,
			clabconstants.PermissionsFileDefault,
		)
		if err != nil {
			log.Warn("Could not create topology backup", "topology path", path,
				"backup path", backupFPath, "error", err)
		}

		return nil
	}
}

// WithTopologyFromLab loads the topology file path based on a running lab name.
// The lab name is used to look up the container labels of a running lab and
// derive the topology file location. It falls back to WithTopoPath once the
// topology path is discovered. varsFile is passed through to WithTopoPath when the
// topology file exists (same as global --vars).
func WithTopologyFromLab(labName string, varsFiles []string) ClabOption {
	return func(c *CLab) error {
		if labName == "" {
			return fmt.Errorf("lab name is required to derive topology path")
		}

		ctx, cancel := context.WithTimeout(context.Background(), topoFromLabListTimeout)
		defer cancel()

		filter := []*clabtypes.GenericFilter{
			{
				FilterType: "label",
				Field:      clabconstants.Containerlab,
				Operator:   "=",
				Match:      labName,
			},
		}

		containers, err := c.globalRuntime().ListContainers(ctx, filter)
		if err != nil {
			return fmt.Errorf("failed to list containers for lab '%s': %w", labName, err)
		}

		if len(containers) == 0 {
			return fmt.Errorf("lab '%s' not found - no running containers", labName)
		}

		topoFile := containers[0].Labels[clabconstants.TopoFile]
		if topoFile == "" {
			return fmt.Errorf("could not determine topology file from container labels")
		}

		// If topology file doesn't exist, fall back to using just the lab name.
		// This allows operations like destroy to work even when the topo file is missing.
		if !clabutils.FileOrDirExists(topoFile) {
			log.Debugf(
				"topology file %s not found for lab %s, using lab name only",
				topoFile,
				labName,
			)
			return WithLabNameOnly(labName)(c)
		}

		log.Debugf("found topology file for lab %s: %s", labName, topoFile)

		return WithTopoPath(topoFile, varsFiles)(c)
	}
}

// WithLabNameOnly sets the lab name without requiring or loading a topology file.
// This is useful for destroy operations where we only need the lab name to find
// and remove containers, without needing the original topology file.
func WithLabNameOnly(labName string) ClabOption {
	return func(c *CLab) error {
		if labName == "" {
			return fmt.Errorf("lab name is required")
		}

		c.Config.Name = labName

		log.Debugf("set lab name to %s (without topology file)", labName)

		// Initialize management network with defaults so destroy can work
		return c.initMgmtNetwork()
	}
}

// WithNodeFilter option sets a filter for nodes to be deployed.
// A filter is a list of node names to be deployed,
// names are provided exactly as they are listed in the topology file.
// Since this is altering the clab.config.Topology.[Nodes,Links] it must only
// be called after WithTopoFile.
func WithNodeFilter(nodeFilter []string) ClabOption {
	return func(c *CLab) error {
		return c.filterClabNodes(nodeFilter)
	}
}

